{
  "operation": {
    "description": "Replaces a trail's body (its description document), for a caller with repo write access rather than a service token — the human/CLI-facing counterpart to the internal editor-content-replace primitive. Send exactly one of markdown or contentJson. By default a non-empty body is refused with 409, which carries the document's current ETag in its ETag header so you can immediately retry with If-Match. Either overwrite:true or a matching If-Match satisfies that guard on its own, since both demonstrate you know what you're replacing; a mismatched If-Match always 412s regardless of overwrite. The write is always attributed to your own session.",
    "operationId": "trailsBodyPut",
    "parameters": [
      {
        "description": "Forge host slug (gh or et)",
        "in": "path",
        "name": "host",
        "required": true,
        "schema": {
          "description": "Forge host slug (gh or et)",
          "type": "string"
        }
      },
      {
        "description": "Repo owner",
        "in": "path",
        "name": "owner",
        "required": true,
        "schema": {
          "description": "Repo owner",
          "type": "string"
        }
      },
      {
        "description": "Repo name",
        "in": "path",
        "name": "repo",
        "required": true,
        "schema": {
          "description": "Repo name",
          "type": "string"
        }
      },
      {
        "description": "Trail number",
        "in": "path",
        "name": "number",
        "required": true,
        "schema": {
          "description": "Trail number",
          "type": "string"
        }
      },
      {
        "description": "Optimistic concurrency: a weak ETag (W/\"<updatedAt>\") from a prior write through this route, or from a 409 response's ETag header. If present, the request 412s when it no longer matches the document's current ETag. A MATCHING If-Match also satisfies the non-empty-document guard on its own — it proves you know the document's current state, so overwrite:true is not needed alongside it. Omit If-Match while leaving overwrite false, and a non-empty document is refused with 409 (carrying its current ETag to retry with) instead.",
        "in": "header",
        "name": "If-Match",
        "schema": {
          "description": "Optimistic concurrency: a weak ETag (W/\"<updatedAt>\") from a prior write through this route, or from a 409 response's ETag header. If present, the request 412s when it no longer matches the document's current ETag. A MATCHING If-Match also satisfies the non-empty-document guard on its own — it proves you know the document's current state, so overwrite:true is not needed alongside it. Omit If-Match while leaving overwrite false, and a non-empty document is refused with 409 (carrying its current ETag to retry with) instead.",
          "type": "string"
        }
      }
    ],
    "requestBody": {
